def R(idx, c, skill, ref, q, a, d, e, trap, level='challenge'):
    if idx < 956:
        changes[idx] = 'Rewritten for correctness, a single defensible answer, and plausible distractors'
    bank[idx] = dict(id=idx, c=c, s=skill, q=q, a=a, d=d, e=e, p=trap, level=level, refs=[ref])
    retired.pop(idx, None)

