for line in ROWS.strip().splitlines():
    fields = line.split('|')
    if len(fields) != 11:
        raise ValueError((len(fields), line))
    idx,c,skill,ref,q,a,d1,d2,d3,e,p = fields
    R(int(idx),c,skill,ref,q,a,[d1,d2,d3],e,p)

